    """Validate an opaque cursor; return its kind tag (``s``/``n``)."""
    if not isinstance(value, str):
        raise ValueError(_CURSOR_INVALID_MESSAGE)
    match = _CURSOR_RE.match(value)
    if match is None:
        raise ValueError(_CURSOR_INVALID_MESSAGE)
    return value[3]


