    """Build several requests in stable keyset order.

    Returns a list of ``(rid, expected, token)`` in submission order;
    accepted rows carry expected ``accepted`` and never appear in a
    batch window. Claims are taken while every lease is still live so
    expired leases cannot be reclaimed ahead of later submissions;
    expiries and terminal finishes are applied only afterwards.
    """
    receipts = [
        store.submit(tenant, f"subject-{i}", ["email"], f"k{i}")
        for i, _kind in enumerate(kinds)
    ]
    # Park unexplainable-processing rows first so they are never
    # treated as claim candidates.
    for receipt, kind in zip(receipts, kinds):
        if kind == "stuck":
            store.transition(tenant, receipt["request_id"], "processing")
    # Claim each lease-taking request in submission (keyset) order.
    tokens: dict[str, str] = {}
    claimable = [
        (receipt, kind)
        for receipt, kind in zip(receipts, kinds)
        if kind in ("live", "expired", "completed", "failed")
    ]
    for receipt, kind in claimable:
        claim = store.claim_next(tenant, "worker", 3600)
        assert claim["request_id"] == receipt["request_id"], (
            claim["request_id"],
            receipt["request_id"],
        )
        tokens[receipt["request_id"]] = claim["claim_token"]
    # Now expire the dead leases and settle the terminals.
    out = []
    for receipt, kind in zip(receipts, kinds):
        rid = receipt["request_id"]
        if kind == "accepted":
            expected, token = "accepted", None
        elif kind == "live":
            expected, token = "processing", tokens[rid]
        elif kind == "expired":
            self._backdate_lease(rid, tenant)
            expected, token = "failed", tokens[rid]
        elif kind == "stuck":
            expected, token = "failed", None
        else:
            store.finish_claim(tenant, rid, tokens[rid], kind)
            expected, token = kind, None
        out.append((rid, expected, token))
    return out

