                tenant, f"subject-{i}", ["email"], f"k{i}"
            )["request_id"]
    out = []
    for i, kind in enumerate(kinds):
        if kind == "accepted":
            out.append((accepted_ids[i], "accepted", None))
        elif kind == "stuck":
            out.append((stuck_ids[i], "failed", None))
        elif kind == "live":
